// Period exports are usable only when their dates exactly match the requested week.
export function weeklyOptionSource(analysis, dates, catalog) {
  const start=dates[0],end=dates.at(-1);
  const sources=(analysis.importSources||[]).filter(s=>s.kind==='options'&&s.start===start&&s.end===end&&s.complete===true);
  const ids=new Set(sources.map(s=>s.id));
  const rows=(analysis.options||[]).filter(r=>ids.has(r.source)&&r.start===start&&r.end===end).map(r=>catalog?.row(r)||r);
  return {start,end,complete:sources.length>0,rows};
}
export const optionFamily=r=>/젤라또|gelato/i.test(r.category||'')?'gelato':/피자|pizza|하프|half/i.test([r.category,r.name].join(' '))?'pizza':null;
export function rankOptions(current,previous,predicate=()=>true){
  const aggregate=source=>{const m=new Map();for(const r of source.rows.filter(predicate)){const name=r.option.normalize('NFKC').trim().replace(/\s+/g,' '),key=name.toLowerCase();if(!m.has(key))m.set(key,{name,count:0,products:new Set()});const x=m.get(key);x.count+=Number(r.selections)||0;x.products.add(r.name)}return m};
  const a=aggregate(current),b=aggregate(previous),keys=new Set([...a.keys(),...b.keys()]);
  return [...keys].map(k=>({name:(a.get(k)||b.get(k)).name,current:current.complete?(a.get(k)?.count||0):null,previous:previous.complete?(b.get(k)?.count||0):null,products:[...(a.get(k)?.products||[])]})).sort((a,b)=>(b.current??-1)-(a.current??-1)||a.name.localeCompare(b.name,'ko'));
}
export function renderWeeklyOptions(c,api){
  const {esc,nf,won,catalog,getAnalysis}=api,analysis=getAnalysis(),a=weeklyOptionSource(analysis,c.active,catalog?.()),b=weeklyOptionSource(analysis,c.prev,catalog?.());
  const familyRows=family=>rankOptions(a,b,r=>optionFamily(r)===family),gelato=familyRows('gelato');
  const format=n=>n===null?'미수집':nf(n)+'회',delta=r=>r.current===null||r.previous===null?'비교 자료 없음':`${r.current-r.previous>0?'+':''}${nf(r.current-r.previous)}회${r.previous?` · ${((r.current-r.previous)/r.previous*100).toFixed(1)}%`:r.current?' · 전주 선택 기록 0':''}`;
  const table=(rows,share=false)=>{const total=rows.reduce((n,r)=>n+(r.current||0),0);return `<div class="table-wrap"><table class="weekly-table"><thead><tr><th>순위</th><th>${share?'플레이버':'선택 옵션'}</th><th class="num">선택 주</th><th class="num">전주</th><th class="num">선택량 변화</th>${share?'<th class="num">선택 비중</th>':''}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${r.current>0?i+1:'—'}</td><td><strong>${esc(r.name)}</strong></td><td class="num"><b>${format(r.current)}</b></td><td class="num">${format(r.previous)}</td><td class="num">${delta(r)}</td>${share?`<td class="num">${total&&r.current!==null?(r.current/total*100).toFixed(1)+'%':'—'}</td>`:''}</tr>`).join('')||`<tr><td colspan="${share?6:5}" class="empty">${a.complete?'이 주차에 선택된 옵션 기록이 없습니다.':'이 주차의 POS 옵션 원본이 아직 없습니다.'}</td></tr>`}</tbody></table></div>`};
  const scope=`<div class="weekly-option-scope"><span class="badge">POS 옵션 기준</span><span>${esc(a.start)}–${esc(a.end)} ${a.complete?'확보':'미수집'} · 전주 ${b.complete?'확보':'미수집'}</span></div>`;
  const productRows=family=>{const map=new Map();for(const r of c.a.filter(r=>optionFamily(r)===family)){const key=r.productId||r.name;if(!map.has(key))map.set(key,{id:key,name:r.name,category:r.category,sales:0,qty:0,unknownQty:false});const x=map.get(key);x.sales+=r.sales;x.qty+=r.qty||0;x.unknownQty||=!!r.unknownQty}return [...map.values()].sort((a,b)=>b.sales-a.sales)};
  const gelatoProducts=productRows('gelato'),pizzaProducts=productRows('pizza');
  const productTable=rs=>`<div class="table-wrap"><table class="weekly-table"><thead><tr><th>상품</th><th class="num">선택 주 상품액</th><th class="num">상품 판매수량</th></tr></thead><tbody>${rs.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td class="num">${won(r.sales)}</td><td class="num">${nf(r.qty)}개${r.unknownQty?' + 미확인':''}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">선택한 채널의 상품 기록이 없습니다.</td></tr>'}</tbody></table></div>`;
  const positives=gelato.filter(r=>r.current>0),high=positives[0],low=[...positives].reverse()[0];
  const pizzaIds=new Map(pizzaProducts.map(r=>[r.id,r]));
  for(const r of [...a.rows,...b.rows].filter(r=>optionFamily(r)==='pizza')){const id=r.productId||r.name;if(!pizzaIds.has(id))pizzaIds.set(id,{id,name:r.name})}
  const pizzas=[...pizzaIds.values()].filter(r=>/하프|half|세트|set/i.test(r.name)).sort((a,b)=>(b.sales||0)-(a.sales||0));
  const forProduct=r=>rankOptions(a,b,x=>(x.productId||x.name)===r.id);
  return `<section class="card weekly-option-section" id="weeklyFlavorReport"><div class="card-head"><div><span class="eyebrow">GELATO</span><h3>젤라또 상품 · 플레이버 실적</h3><p class="sub">상품 판매수량과 맛 선택수량을 함께 확인하세요.</p></div><button class="btn small" id="weeklyOptionExport">↓ 옵션 비교 CSV</button></div><h4>주간 상품 실적</h4><p class="sub">위 상품 분석에서 선택한 채널 기준입니다.</p>${productTable(gelatoProducts)}<h4>플레이버별 선택량 순위</h4>${scope}${high?`<div class="weekly-flavor-highlights"><div><small>가장 많이 선택</small><strong>${esc(high.name)}</strong><b>${format(high.current)}</b></div><div><small>선택 기록 중 가장 적음</small><strong>${esc(low.name)}</strong><b>${format(low.current)}</b></div></div>`:''}<p class="sub">같은 맛의 여러 선택칸은 합산합니다. 한 컵에서 두 가지 맛을 고르면 2회로 집계되어 상품 판매수량과 다릅니다. 배달·네이버 옵션은 이 순위에 포함되지 않습니다.</p>${table(gelato,true)}<details><summary>상품별 플레이버 선택량 보기</summary>${[...new Map([...a.rows,...b.rows].filter(r=>optionFamily(r)==='gelato').map(r=>[r.productId||r.name,r])).values()].map(product=>`<h4>${esc(product.name)}</h4>${table(rankOptions(a,b,r=>(r.productId||r.name)===(product.productId||product.name)),true)}`).join('')||'<p>이 주차의 상품별 옵션 원본이 없습니다.</p>'}</details><details><summary>플레이버별 상품 구성 보기</summary>${gelato.filter(r=>r.current>0).map(r=>`<p><b>${esc(r.name)}</b> · ${r.products.map(esc).join(' / ')}</p>`).join('')||'<p>연결된 플레이버 선택 기록이 없습니다.</p>'}</details><p class="sub">품절·판매 중단 여부가 없어 낮은 선택량을 곧바로 선호도 하락으로 판단하지 않습니다. 다른 기간의 누적 자료를 주간 수량으로 나누지 않습니다.</p></section><section class="card weekly-option-section" id="weeklyPizzaReport"><div class="card-head"><div><span class="eyebrow">PIZZA</span><h3>피자 하프 앤 하프 · 세트 옵션</h3><p class="sub">상품을 펼치면 구성 메뉴별 선택량과 전주 변화를 볼 수 있습니다.</p></div></div>${scope}${pizzas.map(r=>`<details class="weekly-pizza-options" open><summary><strong>${esc(r.name)}</strong><span>${r.qty!==undefined?'상품 '+nf(r.qty)+'개 · '+won(r.sales):'전주 또는 옵션 원본에서 확인'}</span></summary>${table(forProduct(r))}</details>`).join('')||'<div class="empty">연결된 하프 앤 하프·피자 세트 상품이 없습니다.</div>'}<p class="sub">하프 앤 하프는 선택한 두 메뉴를 각각 1회로 계산합니다. 세트의 피자·음료 등 옵션명을 그대로 표시합니다. 옵션 금액은 상품 매출에 다시 더하지 않습니다.</p></section>`;
}
